-- Let's trace the path from account to securitydetection
-- account -> profile -> sessionbehavior -> contentbehavior -> moderationaction -> securitydetection
SELECT COUNT(*) as total_accounts FROM account;

SELECT detection_score_profile->'overall'->>'threatlvl' as threat_level, 
       detection_score_profile->'overall'->>'riskval' as risk_val
FROM securitydetection LIMIT 10;
